#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct Complex {
    re: i32,
    im: i32,
}

fn real_if_close(arr: Vec<Complex>, tol: i32) -> Vec<Complex> {
    // Fixed machine epsilon as specified
    let eps = 2;
    let threshold = tol * eps;

    // Check if every element's imaginary part is "close to zero"
    let all_close = arr.iter().all(|c| c.im.abs() <= threshold);

    if all_close {
        // Further check if all imaginary parts are exactly zero:
        // If input is already real, return it unchanged (preserves same instance)
        if arr.iter().all(|c| c.im == 0) {
            arr
        } else {
            // Otherwise, zero all imaginary parts but keep real parts same
            arr.into_iter()
                .map(|c| Complex { re: c.re, im: 0 })
                .collect()
        }
    } else {
        // If not all close, return original array unchanged
        arr
    }
}